let BruteThreshold = 20;
let Brute =
    union isfuzzy=true
        (W3CIISLog | where TimeGenerated > ago(1d) | where csMethod == "POST" and csUriStem =~ "/admin/check" | project TimeGenerated, SrcIp=cIP, Host=Computer),
        (AppServiceHTTPLogs | where TimeGenerated > ago(1d) | where CsMethod == "POST" and CsUriStem =~ "/admin/check" | project TimeGenerated, SrcIp=CIp, Host=CsHost),
        (ImWebSession | where TimeGenerated > ago(1d) | where HttpMethod =~ "POST" and Url has "/admin/check" | project TimeGenerated, SrcIp=SrcIpAddr, Host=DstHostname)
    | summarize BruteAttempts=count(), BruteFirst=min(TimeGenerated), BruteLast=max(TimeGenerated) by SrcIp, Host
    | where BruteAttempts >= BruteThreshold;
let AdminLand =
    union isfuzzy=true
        (W3CIISLog | where TimeGenerated > ago(1d) | where csMethod == "GET" and csUriStem in~ ("/admin/","/admin/index.php","/admin/dashboard") and scStatus in ("200","302") | project AdminTime=TimeGenerated, SrcIp=cIP, Host=Computer, Uri=csUriStem, Status=scStatus),
        (AppServiceHTTPLogs | where TimeGenerated > ago(1d) | where CsMethod == "GET" and CsUriStem in~ ("/admin/","/admin/index.php","/admin/dashboard") and ScStatus in (200,302) | project AdminTime=TimeGenerated, SrcIp=CIp, Host=CsHost, Uri=CsUriStem, Status=tostring(ScStatus)),
        (ImWebSession | where TimeGenerated > ago(1d) | where HttpMethod =~ "GET" and Url has_any ("/admin/","/admin/index.php","/admin/dashboard") and HttpStatusCode in (200,302) | project AdminTime=TimeGenerated, SrcIp=SrcIpAddr, Host=DstHostname, Uri=Url, Status=tostring(HttpStatusCode));
